// Returns the phone id of `sym`, or -1 when unknown (caller maps
// unknown phones to "UNK" like clean_text does).
inline int symbols2Id(std::string_view sym) {
    int lo = 0, hi = kSymbols2Count;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        std::string_view s{kSymbols2[kSymbols2SortedById[mid]]};
        if (s < sym) lo = mid + 1;
        else if (s > sym) hi = mid;
        else return static_cast<int>(kSymbols2SortedById[mid]);
    }
    return -1;
}

